for (const [code, entries] of Object.entries(homeTranslations)) {
  translations[code] = { ...translations[code], ...entries }
}

type ContextValue={language:LanguageCode,setLanguage:(code:LanguageCode)=>void,t:(key:Key)=>string}
const LanguageContext=createContext<ContextValue>({language:'en',setLanguage:()=>{},t:key=>keys[key]})
export function LanguageProvider({children}:{children:ReactNode}){
 const [language,setLanguage]=useState<LanguageCode>(()=>{try{const stored=localStorage.getItem('betnova-language');return languages.some(l=>l.code===stored)?stored as LanguageCode:'en'}catch{return 'en'}})
 useEffect(()=>{try{localStorage.setItem('betnova-language',language)}catch{};document.documentElement.lang=language;document.documentElement.dir=language==='ar'||language==='ur'?'rtl':'ltr'},[language])
 const value=useMemo(()=>({language,setLanguage,t:(key:Key)=>translations[language]?.[key]??keys[key]}),[language])
 return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>
}
export function useLanguage(){return useContext(LanguageContext)}
